content:
write: {"content": "# Аудит ВПС

## Сбор сведений
Выполняется...", "path": "audit_report.md"}

bash: {"command": "{
  echo "## Ядро и ОС" > /tmp/audit_os.txt;
  uname -r >> /tmp/audit_os.txt;
  cat /etc/os-release 2>>/tmp/audit_os.txt || echo "Нет /etc/os-release" >> /tmp/audit_os.txt;
  echo "" >> /tmp/audit_os.txt;
  echo "## Время и uptime" >> /tmp/audit_os.txt;
  date '+%F %T %Z' >> /tmp/audit_os.txt;
  uptime -p >> /tmp/audit_os.txt;
  cat /tmp/audit_os.txt
}"}

bash: {"command": "{
  echo "## Пользователи и группы" > /tmp/audit_users.txt;
  echo "--- /etc/passwd (первые 20 строк) ---" >> /tmp/audit_users.txt;
  head -n 20 /etc/passwd >> /tmp/audit_users.txt;
  echo "" >> /tmp/audit_users.txt;
  echo "--- /etc/group (первые 20 строк) ---" >> /tmp/audit_users.txt;
  head -n 20 /etc/group >> /tmp/audit_users.txt;
  echo "" >> /tmp/audit_users.txt;
  echo "--- Пользователи с UID 0 ---" >> /tmp/audit_users.txt;
  awk -F: '$3==0{print $1}' /etc/passwd >> /tmp/audit_users.txt;
  echo "" >> /tmp/audit_users.txt;
  echo "--- Группы с GID 0 ---" >> /tmp/audit_users.txt;
  awk -F: '$3==0{print $1}' /etc/group >> /tmp/audit_users.txt;
  echo "" >> /tmp/audit_users.txt;
  echo "--- Последние входы (last -n 20) ---" >> /tmp/audit_users.txt;
  last -n 20 2>/dev/null || echo "last недоступен" >> /tmp/audit_users.txt;
  cat /tmp/audit_users.txt
}"}

bash: {"command": "{
  echo "## Сеть: интерфейсы и маршруты" > /tmp/audit_net.txt;
  ip -brief addr show >> /tmp/audit_net.txt;
  echo "" >> /tmp/audit_net.txt;
  ip -brief route show >> /tmp/audit_net.txt;
  echo "" >> /tmp/audit_net.txt;
  echo "## Сеть: открытые порты (TCP/UDP)" >> /tmp/audit_net.txt;
  ss -tulpen 2>/dev/null | head -n 100 >> /tmp/audit_net.txt || netstat -tulpen 2>/dev/null | head -n 100 >> /tmp/audit_net.txt;
  cat /tmp/audit_net.txt
}"}

bash: {"command": "{
  echo "## Службы (systemd)" > /tmp/audit_services.txt;
  systemctl list-unit-files --type=service --state=enabled --no-pager 2>/dev/null | head -n 100 >> /tmp/audit_services.txt;
  echo "" >> /tmp/audit_services.txt;
  echo "--- Активные службы (running) ---" >> /tmp/audit_services.txt;
  systemctl list-units --type=service --state=running --no-pager 2>/dev/null | head -n 100 >> /tmp/audit_services.txt;
  cat /tmp/audit_services.txt
}"}

bash: {"command": "{
  echo "## Диски и иноды" > /tmp/audit_fs.txt;
  df -hT | head -n 20 >> /tmp/audit_fs.txt;
  echo "" >> /tmp/audit_fs.txt;
  df -i | head -n 20 >> /tmp/audit_fs.txt;
  echo "" >> /tmp/audit_fs.txt;
  lsblk -d -o NAME,SIZE,TYPE,ROTA,MODEL 2>/dev/null | head -n 20 >> /tmp/audit_fs.txt || echo "lsblk недоступен" >> /tmp/audit_fs.txt;
  cat /tmp/audit_fs.txt
}"}

bash: {"command": "{
  echo "## Логи (последние 50 строк)" > /tmp/audit_logs.txt;
  echo "--- /var/log/syslog ---" >> /tmp/audit_logs.txt;
  tail -n 50 /var/log/syslog 2>/dev/null || echo "Нет /var/log/syslog" >> /tmp/audit_logs.txt;
  echo "" >> /tmp/audit_logs.txt;
  echo "--- /var/log/auth.log ---" >> /tmp/audit_logs.txt;
  tail -n 50 /var/log/auth.log 2>/dev/null || echo "Нет /var/log/auth.log" >> /tmp/audit_logs.txt;
  echo "" >> /tmp/audit_logs.txt;
  echo "--- journalctl -n 50 (system) ---" >> /tmp/audit_logs.txt;
  journalctl -n 50 --no-pager 2>/dev/null | tail -n 50 >> /tmp/audit_logs.txt || echo "journalctl недоступен" >> /tmp/audit_logs.txt;
  cat /tmp/audit_logs.txt
}"}

bash: {"command": "{
  echo "## Установленное ПО и версии" > /tmp/audit_software.txt;
  echo "--- uname -a ---" >> /tmp/audit_so.txt;
  uname -a >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- lsb_release -a ---" >> /tmp/audit_so.txt;
  lsb_release -a 2>/dev/null || echo "lsb_release недоступен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- systemd --version ---" >> /tmp/audit_so.txt;
  systemd --version 2>/dev/null || echo "systemd --version недоступен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- nginx -v ---" >> /tmp/audit_so.txt;
  nginx -v 2>&1 >> /tmp/audit_so.txt || echo "nginx не установлен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- python3 --version ---" >> /tmp/audit_so.txt;
  python3 --version 2>&1 >> /tmp/audit_so.txt || echo "python3 не установлен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- node --version ---" >> /tmp/audit_so.txt;
  node --version 2>&1 >> /tmp/audit_so.txt || echo "node не установлен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- docker --version ---" >> /tmp/audit_so.txt;
  docker --version 2>&1 >> /tmp/audit_so.txt || echo "docker не установлен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- git --version ---" >> /tmp/audit_so.txt;
  git --version 2>&1 >> /tmp/audit_so.txt || echo "git не установлен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- fail2ban-server --version ---" >> /tmp/audit_so.txt;
  fail2ban-server --version 2>&1 >> /tmp/audit_so.txt || echo "fail2ban не установлен" >> /tmp/audit_so.txt;
  echo "" >> /tmp/audit_so.txt;
  echo "--- ufw --version ---" >> /tmp/audit_so.txt;
  ufw --version 2>&1 >> /tmp/audit_so.txt || echo "ufw не установлен" >> /tmp/audit_so.txt;
  cat /tmp/audit_so.txt
}"}

bash: {"command": "{
  echo "## Базовые признаки безопасности" > /tmp/audit_sec.txt;
  echo "--- Права на ключевые файлы ---" >> /tmp/audit_sec.txt;
  echo "/etc/ssh/sshd_config:" >> /tmp/audit_sec.txt;
  ls -l /etc/ssh/sshd_config 2>/dev/null || echo "нет файла" >> /tmp/audit_sec.txt;
  echo "" >> /tmp/audit_sec.txt;
  echo "/etc/sudoers:" >> /tmp/audit_sec.txt;
  ls -l /etc/sudoers 2>/dev/null || echo "нет файла" >> /tmp/audit_sec.txt;
  echo "" >> /tmp/audit_sec.txt;
  echo "/etc/passwd:" >> /tmp/audit_sec.txt;
  ls -l /etc/passwd 2>/dev/null || echo "нет файла" >> /tmp/audit_sec.txt;
  echo "" >> /tmp/audit_sec.txt;
  echo "/etc/group:" >> /tmp/audit_sec.txt;
  ls -l /etc/group 2>/dev/null || echo "нет файла" >> /tmp/audit_sec.txt;
  echo "" >> /tmp/audit_sec.txt;
  echo "--- SSH: вход root (PermitRootLogin) ---" >> /tmp/audit_sec.txt;
  if [ -f /etc/ssh/sshd_config ]; then
    grep -i '^PermitRootLogin' /etc/ssh/sshd_config | head -n 5 >> /tmp/audit_sec.txt || echo "директива не найдена" >> /tmp/audit_sec.txt;
  else
    echo "нет /etc/ssh/sshd_config" >> /tmp/audit_sec.txt;
  fi
  echo "" >> /tmp/audit_sec.txt;
  echo "--- Парольная политика: PAM common-auth (pam_unix.so) ---" >> /tmp/audit_sec.txt;
  if [ -f /etc/pam.d/common-auth ]; then
    grep -n 'pam_unix.so' /etc/pam.d/common-auth | head -n 5 >> /tmp/audit_sec.txt || echo "не найдено pam_unix.so" >> /tmp/audit_sec.txt;
  else
    echo "нет /etc/pam.d/common-auth" >> /tmp/audit_sec.txt;
  fi
  echo "" >> /tmp/audit_sec.txt;
  echo "--- Fail2ban: статус jail'ов ---" >> /tmp/audit_sec.txt;
  fail2ban-client status 2>/dev/null | head -n 50 >> /tmp/audit_sec.txt || echo "fail2ban-client недоступен" >> /tmp/audit_sec.txt;
  echo "" >> /tmp/audit_sec.txt;
  echo "--- UFW: статус ---" >> /tmp/audit_sec.txt;
  ufw status 2>/dev/null || echo "ufw не установлен или неактивен" >> /tmp/audit_sec.txt;
  cat /tmp/audit_sec.txt
}"}
